!function(){"use strict";const e=[{id:"aryabhata",name:"Aryabhata",period:"476 – c. 550 CE",field:"Mathematics & Astronomy",contribution:"Approximation of pi and astronomical calculations.",details:"Aryabhata was an influential mathematician and astronomer of ancient India. He accurately calculated the value of pi to four decimal places and proposed a heliocentric model of the solar system where the Earth spins on its axis."},{id:"brahmagupta",name:"Brahmagupta",period:"c. 598 – c. 668 CE",field:"Mathematics & Astronomy",contribution:"First to give rules to compute with zero.",details:"His major work, the Brahmasphutasiddhanta, contains the first mathematical treatment of zero and rules for arithmetic involving negative numbers."},{id:"jc-bose",name:"Jagadish Chandra Bose",period:"1858 – 1937",field:"Physics & Plant Physiology",contribution:"Pioneered the investigation of radio and microwave optics.",details:"Bose demonstrated that plants have feeling through his invention of the crescograph. He was also a pioneer in the field of microwave transmission, predating many other scientists in wireless communication."},{id:"srinivasa-ramanujan",name:"Srinivasa Ramanujan",period:"1887 – 1920",field:"Mathematics",contribution:"Extraordinary contributions to mathematical analysis, number theory, and continued fractions.",details:"Despite having almost no formal training in pure mathematics, Ramanujan made substantial contributions to the analytical theory of numbers and worked on elliptic functions and infinite series."},{id:"cv-raman",name:"C. V. Raman",period:"1888 – 1970",field:"Physics",contribution:"Discovery of the Raman Effect.",details:"His work on the scattering of light earned him the Nobel Prize in Physics in 1930. The Raman Effect is the inelastic scattering of a photon by molecules which are excited to higher vibrational or rotational energy levels."},{id:"satyendra-nath-bose",name:"Satyendra Nath Bose",period:"1894 – 1974",field:"Theoretical Physics",contribution:"Foundation for Bose-Einstein statistics and the theory of the Bose-Einstein condensate.",details:"He collaborated with Albert Einstein to develop a statistical method to describe the behavior of subatomic particles, which later came to be known as 'bosons' in his honor."},{id:"meghnad-saha",name:"Meghnad Saha",period:"1893 – 1956",field:"Astrophysics",contribution:"Developed the Saha ionization equation.",details:"His equation is used to describe chemical and physical conditions in stars, allowing astronomers to accurately relate the spectral classes of stars to their actual temperatures."},{id:"homi-bhabha",name:"Homi J. Bhabha",period:"1909 – 1966",field:"Nuclear Physics",contribution:"Father of the Indian nuclear programme.",details:"Bhabha played a central role in the development of India's nuclear energy program and founded the Tata Institute of Fundamental Research (TIFR) and the Bhabha Atomic Research Centre (BARC)."},{id:"vikram-sarabhai",name:"Vikram Sarabhai",period:"1919 – 1971",field:"Space Science & Physics",contribution:"Father of the Indian space programme.",details:"Sarabhai was instrumental in establishing the Indian Space Research Organisation (ISRO). He also helped establish the Physical Research Laboratory in Ahmedabad."},{id:"apj-abdul-kalam",name:"A. P. J. Abdul Kalam",period:"1931 – 2015",field:"Aerospace Engineering",contribution:"Key role in the development of India's missile and nuclear weapons programs.",details:"Often referred to as the 'Missile Man of India', Dr. Kalam was deeply involved in India's civilian space programme and military missile development efforts before serving as the 11th President of India."}];document.addEventListener("DOMContentLoaded",function(){!function(){const t=document.getElementById("timeline-container");t&&e.forEach(e=>{const a=document.createElement("div");a.className="scientist-card-wrapper";const i=document.createElement("div");i.className="timeline-marker";const n=document.createElement("article");n.className="scientist-card",n.id=`card-${e.id}`;const o=document.createElement("span");o.className="scientist-year",o.textContent=e.period;const s=document.createElement("h2");s.textContent=e.name;const r=document.createElement("p");r.className="scientist-field",r.textContent=e.field;const d=document.createElement("div");d.className="scientist-content";const c=document.createElement("strong");c.textContent="Major Contribution: ",d.appendChild(c),d.appendChild(document.createTextNode(e.contribution));const l=document.createElement("div");l.className="scientist-details",l.id=`details-${e.id}`,l.textContent=e.details;const h=document.createElement("button");h.type="button",h.className="btn-details",h.textContent="View Details",h.setAttribute("aria-expanded","false"),h.setAttribute("aria-controls",`details-${e.id}`),h.addEventListener("click",()=>{"true"===h.getAttribute("aria-expanded")?(h.setAttribute("aria-expanded","false"),h.textContent="View Details",l.classList.remove("open")):(h.setAttribute("aria-expanded","true"),h.textContent="Hide Details",l.classList.add("open"))}),n.appendChild(o),n.appendChild(s),n.appendChild(r),n.appendChild(d),n.appendChild(h),n.appendChild(l),a.appendChild(i),a.appendChild(n),t.appendChild(a)})}(),function(){const e=document.querySelectorAll(".scientist-card");if(window.matchMedia("(prefers-reduced-motion: reduce)").matches||!("IntersectionObserver"in window))return void e.forEach(e=>e.classList.add("scientist-card-visible"));const t=new IntersectionObserver(e=>{e.forEach(e=>{e.isIntersecting&&(e.target.classList.add("scientist-card-visible"),t.unobserve(e.target))})},{root:null,threshold:.15,rootMargin:"0px 0px -50px 0px"});e.forEach(e=>t.observe(e))}()})}();